function clearNavigationSwipeVisuals() {
  navigationDrawer.classList.remove("swiping");
  navigationPanel.style.removeProperty("transform");
  navigationBackdrop.style.removeProperty("opacity");
}

function resetNavigationSwipeState() {
  navigationSwipePointerId = null;
  navigationSwipeStartX = null;
  navigationSwipeStartY = null;
  navigationSwipeStartedAt = 0;
  navigationSwipeActive = false;
}

function scheduleNavigationSwipeClickReset() {
  window.clearTimeout(navigationSwipeResetTimer);
  navigationSwipeResetTimer = window.setTimeout(() => {
    navigationSwipeClickBlocked = false;
  }, 420);
}

function openNavigationDrawer() {
  if (navigationDrawer.classList.contains("open")) {
    return;
  }

  window.clearTimeout(navigationCloseTimer);
  navigationDrawer.classList.remove("closing", "swiping");
  clearNavigationSwipeVisuals();
  resetNavigationSwipeState();

  // 모바일 브라우저가 숨김 상태와 열린 상태를 한 번에 계산하면
  // 첫 번째 탭에서 패널이 화면 밖에 남는 경우가 있어,
  // 먼저 표시 상태를 확정한 뒤 열린 위치로 전환합니다.
  navigationDrawer.classList.add("opening");
  navigationDrawer.setAttribute("aria-hidden", "false");
  menuButton.setAttribute("aria-expanded", "true");
  document.body.classList.add("navigation-open");

  void navigationDrawer.offsetWidth;

  navigationDrawer.classList.add("open");
  navigationDrawer.classList.remove("opening");

  window.requestAnimationFrame(() => {
    navigationDrawer
      .querySelector(".navigation-item.active")
      ?.focus();
  });
}

function closeNavigationDrawer({ fromSwipe = false } = {}) {
  if (
    !navigationDrawer.classList.contains("open") &&
    !navigationDrawer.classList.contains("closing")
  ) {
    return;
  }

  window.clearTimeout(navigationCloseTimer);
  navigationDrawer.classList.remove("swiping");
  navigationDrawer.classList.add("closing");
  navigationDrawer.classList.remove("open");
  navigationDrawer.setAttribute("aria-hidden", "true");
  menuButton.setAttribute("aria-expanded", "false");
  document.body.classList.remove("navigation-open");

  if (fromSwipe) {
    window.requestAnimationFrame(() => {
      navigationPanel.style.transform = "translateX(-104%)";
      navigationBackdrop.style.opacity = "0";
    });
  }

  navigationCloseTimer = window.setTimeout(() => {
    navigationDrawer.classList.remove("closing");
    clearNavigationSwipeVisuals();
    resetNavigationSwipeState();
    menuButton.focus({ preventScroll: true });
  }, 300);
}

function handleNavigationSwipeStart(event) {
  if (
    !navigationDrawer.classList.contains("open") ||
    !["touch", "pen"].includes(event.pointerType)
  ) {
    return;
  }

  window.clearTimeout(navigationSwipeResetTimer);
  navigationSwipePointerId = event.pointerId;
  navigationSwipeStartX = event.clientX;
  navigationSwipeStartY = event.clientY;
  navigationSwipeStartedAt = performance.now();
  navigationSwipeActive = false;
}

function handleNavigationSwipeMove(event) {
  if (
    event.pointerId !== navigationSwipePointerId ||
    navigationSwipeStartX === null ||
    navigationSwipeStartY === null
  ) {
    return;
  }

  const deltaX = event.clientX - navigationSwipeStartX;
  const deltaY = event.clientY - navigationSwipeStartY;
  const absoluteX = Math.abs(deltaX);
  const absoluteY = Math.abs(deltaY);

  if (!navigationSwipeActive) {
    if (absoluteY > 12 && absoluteY > absoluteX) {
      resetNavigationSwipeState();
      return;
    }

    if (deltaX >= -8 || absoluteX <= absoluteY) {
      return;
    }

    navigationSwipeActive = true;
    navigationSwipeClickBlocked = true;
    navigationDrawer.classList.add("swiping");

    try {
      navigationPanel.setPointerCapture(event.pointerId);
    } catch (error) {
      // 일부 모바일 브라우저에서는 포인터 캡처를 지원하지 않을 수 있습니다.
    }
  }

  event.preventDefault();

  const panelWidth = Math.max(
    navigationPanel.getBoundingClientRect().width,
    1,
  );
  const translateX = Math.max(-panelWidth, Math.min(0, deltaX));
  const progress = Math.min(1, Math.abs(translateX) / panelWidth);

  navigationPanel.style.transform = `translateX(${translateX}px)`;
  navigationBackdrop.style.opacity = String(1 - progress);
}

function handleNavigationSwipeEnd(event) {
  if (event.pointerId !== navigationSwipePointerId) {
    return;
  }

  const deltaX =
    navigationSwipeStartX === null
      ? 0
      : event.clientX - navigationSwipeStartX;
  const duration = Math.max(
    performance.now() - navigationSwipeStartedAt,
    1,
  );
  const velocityX = deltaX / duration;
  const panelWidth = Math.max(
    navigationPanel.getBoundingClientRect().width,
    1,
  );
  const shouldClose =
    navigationSwipeActive &&
    (Math.abs(deltaX) >= Math.min(88, panelWidth * 0.26) ||
      (deltaX <= -34 && velocityX <= -0.45));

  try {
    if (navigationPanel.hasPointerCapture(event.pointerId)) {
      navigationPanel.releasePointerCapture(event.pointerId);
    }
  } catch (error) {
    // 일부 모바일 브라우저에서는 포인터 캡처를 지원하지 않을 수 있습니다.
  }

  if (shouldClose) {
    closeNavigationDrawer({ fromSwipe: true });
    scheduleNavigationSwipeClickReset();
    return;
  }

  if (navigationSwipeActive) {
    navigationDrawer.classList.remove("swiping");
    navigationPanel.style.transform = "translateX(0)";
    navigationBackdrop.style.opacity = "1";

    window.clearTimeout(navigationSwipeResetTimer);
    navigationSwipeResetTimer = window.setTimeout(() => {
      clearNavigationSwipeVisuals();
      navigationSwipeClickBlocked = false;
    }, 300);
  }

  resetNavigationSwipeState();
}

function handleNavigationSwipeCancel(event) {
  if (event.pointerId !== navigationSwipePointerId) {
    return;
  }

  if (navigationSwipeActive) {
    navigationDrawer.classList.remove("swiping");
    navigationPanel.style.transform = "translateX(0)";
    navigationBackdrop.style.opacity = "1";

    window.clearTimeout(navigationSwipeResetTimer);
    navigationSwipeResetTimer = window.setTimeout(() => {
      clearNavigationSwipeVisuals();
      navigationSwipeClickBlocked = false;
    }, 300);
  }

  resetNavigationSwipeState();
}

function setAppPage(pageId) {
  const targetPage = appPages.find(
    (page) => page.dataset.appPage === pageId,
  );

  if (!targetPage) {
    return;
  }

  currentAppPage = pageId;
  document.documentElement.classList.toggle(
    "hours-leave-page-active",
    pageId === "hours-leave",
  );
  updateSalaryScrollSnapState();
  if (pageId === "hours-leave") {
    appPageTitle.innerHTML =
      '<span class="hours-leave-hours">52h</span><span class="hours-leave-rest"> / 연차</span>';
    appPageTitle.classList.add("hours-leave-title");
  } else {
    appPageTitle.textContent =
      APP_PAGE_TITLES[pageId] || "근태관리";
    appPageTitle.classList.remove("hours-leave-title");
  }

  appPages.forEach((page) => {
    const isActive = page === targetPage;

    page.hidden = !isActive;
    page.classList.toggle("active", isActive);
    page.setAttribute("aria-hidden", String(!isActive));
  });

  appNavigationButtons.forEach((button) => {
    const isActive = button.dataset.appNavigation === pageId;

    button.classList.toggle("active", isActive);

    if (isActive) {
      button.setAttribute("aria-current", "page");
    } else {
      button.removeAttribute("aria-current");
    }
  });

  closeNavigationDrawer();
  closeSalaryYearPicker();
  closeAnnualLeaveYearPicker();

  if (pageId === "salary") {
    salaryMobilePageIndex = 0;
    salaryMobilePageTransitioning = false;
    salaryMobileCollapseAfterTransition = false;
    salaryMobileCollapseSettingsAfterTransition = false;
    salaryMobilePendingBonusOpen = false;
    salaryMobilePendingDetailOpen = false;
    salaryBonusOpen = false;
    updateSalaryBonusVisibility({ skipPagerSync: true });
    syncSalaryInputs();
    renderBonusEditor();
    renderSalary();

    requestAnimationFrame(() => {
      updateSalaryScrollSnapState();
      updateSalaryMobilePagerHeight();
      applySalaryMobilePageState({ immediate: true });
    });
  }

  if (pageId === "hours-leave") {
    syncWeeklyDateRangeInputs();
    render52HourCalculator();
    renderAnnualLeaveSummary();
  }

  syncMobilePagerMode();

  if (pageId === "hours-leave") {
    document.documentElement.classList.remove(
      "mobile-pager-enabled",
      "salary-mobile-pager-enabled",
    );

    [
      "transform",
      "top",
      "inset",
      "height",
      "min-height",
    ].forEach((propertyName) => {
      targetPage.style.removeProperty(propertyName);
    });

    targetPage.scrollTop = 0;
    if (appMain) {
      appMain.scrollTop = 0;
    }

    document.scrollingElement?.scrollTo({
      top: 0,
      left: 0,
      behavior: "auto",
    });

    requestAnimationFrame(() => {
      targetPage.scrollTop = 0;
      if (appMain) {
        appMain.scrollTop = 0;
      }
      document.scrollingElement?.scrollTo({
        top: 0,
        left: 0,
        behavior: "auto",
      });
    });
  } else {
    window.scrollTo({ top: 0, behavior: "smooth" });
  }
}

function openSalaryYearPicker() {
  renderYearScrollPicker(salaryYearScroller, salarySelectedYear);
  salaryYearPicker.hidden = false;
  salaryYearButton.setAttribute("aria-expanded", "true");

  window.requestAnimationFrame(() => {
    scrollYearPickerToSelected(salaryYearScroller);
    salaryYearScroller
      .querySelector("[aria-selected=\"true\"]")
      ?.focus({ preventScroll: true });
  });
}

function closeSalaryYearPicker() {
  salaryYearPicker.hidden = true;
  salaryYearButton.setAttribute("aria-expanded", "false");
}

async function changeSalaryYear(
  direction,
  { animate = true } = {},
) {
  if (
    salaryYearAnimating ||
    !Number.isFinite(direction) ||
    direction === 0
  ) {
    return;
  }

  const normalizedDirection = direction > 0 ? 1 : -1;
  const nextYear = clampYear(
    salarySelectedYear + normalizedDirection,
  );

  if (nextYear === salarySelectedYear) {
    return;
  }

  const updateYear = () => {
    setSalaryYear(nextYear);
  };

  salaryYearAnimating = true;

  try {
    if (!animate) {
      updateYear();
      return;
    }

    /*
     * 근태관리 달력의 월 화살표와 같은 전환 함수를 그대로 사용한다.
     */
    await animateMonthTransition(
      salaryYearGrid,
      normalizedDirection,
      updateYear,
    );
  } finally {
    salaryYearAnimating = false;
  }
}

function setSalaryYear(year) {
  salarySelectedYear = clampYear(year);
  syncSalaryInputs();
  renderBonusEditor();
  renderSalary();
}

function openAnnualLeaveYearPicker() {
  renderYearScrollPicker(
    annualLeaveYearScroller,
    annualLeaveSelectedYear,
  );
  annualLeaveYearPicker.hidden = false;
  annualLeaveYearButton.setAttribute("aria-expanded", "true");

  window.requestAnimationFrame(() => {
    scrollYearPickerToSelected(annualLeaveYearScroller);
  });
}

function closeAnnualLeaveYearPicker() {
  annualLeaveYearPicker.hidden = true;
  annualLeaveYearButton.setAttribute("aria-expanded", "false");
}

function clampYear(year) {
  const numericYear = Number(year);

  if (!Number.isFinite(numericYear)) {
    return new Date().getFullYear();
  }

  return Math.min(
    YEAR_MAX,
    Math.max(YEAR_MIN, Math.trunc(numericYear)),
  );
}

function renderYearScrollPicker(container, selectedYear) {
  container.innerHTML = Array.from(
    { length: YEAR_MAX - YEAR_MIN + 1 },
    (_, index) => {
      const year = YEAR_MIN + index;
      const isSelected = year === selectedYear;

      return `
        <button
          class="year-scroll-option${isSelected ? " selected" : ""}"
          type="button"
          role="option"
          data-year-option="${year}"
          aria-selected="${isSelected}"
        >
          ${year}년
        </button>
      `;
    },
  ).join("");
}

function scrollYearPickerToSelected(container) {
  const selectedOption = container.querySelector(
    "[aria-selected=\"true\"]",
  );

  selectedOption?.scrollIntoView({
    block: "center",
    behavior: "auto",
  });
}

function openDatePicker(input) {
  const selectedDate = parseDateInputValue(input.value);
  const today = new Date();

  datePickerTargetInput = input;
  datePickerPreviousFocus = document.activeElement;
  datePickerVisibleMonth = selectedDate
    ? new Date(
        selectedDate.getUTCFullYear(),
        selectedDate.getUTCMonth(),
        1,
      )
    : new Date(
        today.getFullYear(),
        today.getMonth(),
        1,
      );

  renderDatePicker();
  datePickerModal.classList.add("open");
  datePickerModal.setAttribute("aria-hidden", "false");

  window.requestAnimationFrame(() => {
    const focusTarget =
      datePickerGrid.querySelector(".selected") ||
      datePickerGrid.querySelector(".today") ||
      datePickerGrid.querySelector("button");

    focusTarget?.focus();
  });
}

function closeDatePicker() {
  if (!datePickerModal.classList.contains("open")) {
    return;
  }

  datePickerModal.classList.remove("open");
  datePickerModal.setAttribute("aria-hidden", "true");

  const focusTarget = datePickerPreviousFocus;

  datePickerTargetInput = null;
  datePickerPreviousFocus = null;
  focusTarget?.focus();
}

function openMonthPicker(target) {
  monthPickerTarget = target;
  monthPickerPreviousFocus = document.activeElement;

  const sourceMonth =
    target === "datePicker"
      ? datePickerVisibleMonth
      : currentMonth;

  monthPickerSelectedYear = sourceMonth.getFullYear();
  monthPickerYearScroller.hidden = true;
  monthPickerYearButton.setAttribute("aria-expanded", "false");
  renderMonthPickerMonths();

  monthPickerModal.classList.add("open");
  monthPickerModal.setAttribute("aria-hidden", "false");

  window.requestAnimationFrame(() => {
    closeMonthPickerButton.focus({ preventScroll: true });
  });
}

function closeMonthPicker() {
  if (!monthPickerModal.classList.contains("open")) {
    return;
  }

  monthPickerModal.classList.remove("open");
  monthPickerModal.setAttribute("aria-hidden", "true");
  monthPickerYearScroller.hidden = true;
  monthPickerYearButton.setAttribute("aria-expanded", "false");

  const focusTarget = monthPickerPreviousFocus;

  monthPickerTarget = null;
  monthPickerPreviousFocus = null;
  focusTarget?.focus();
}

function getMonthPickerYear() {
  return monthPickerSelectedYear;
}

function setMonthPickerYear(year) {
  monthPickerSelectedYear = clampYear(year);
  renderMonthPickerMonths();

  if (!monthPickerYearScroller.hidden) {
    renderYearScrollPicker(
      monthPickerYearScroller,
      monthPickerSelectedYear,
    );
    scrollYearPickerToSelected(monthPickerYearScroller);
  }
}

function renderMonthPickerMonths() {
  const sourceMonth =
    monthPickerTarget === "datePicker"
      ? datePickerVisibleMonth
      : currentMonth;
  const selectedYear = getMonthPickerYear();

  monthPickerYearButton.textContent = `${selectedYear}년`;

  monthPickerMonths.forEach((button, monthIndex) => {
    const isActive =
      selectedYear === sourceMonth.getFullYear() &&
      monthIndex === sourceMonth.getMonth();

    button.classList.toggle("active", isActive);

    if (isActive) {
      button.setAttribute("aria-current", "date");
    } else {
      button.removeAttribute("aria-current");
    }
  });
}

function applyMonthPickerSelection(monthIndex) {
  const selectedYear = getMonthPickerYear();

  if (monthPickerTarget === "datePicker") {
    datePickerVisibleMonth = new Date(
      selectedYear,
      monthIndex,
      1,
    );
    renderDatePicker();
  } else {
    currentMonth = new Date(selectedYear, monthIndex, 1);
    render();
  }

  closeMonthPicker();
}

async function changeMainCalendarMonth(
  direction,
  { animate = true } = {},
) {
  if (mainCalendarMonthAnimating) {
    return;
  }

  const updateMonth = () => {
    currentMonth = new Date(
      currentMonth.getFullYear(),
      currentMonth.getMonth() + direction,
      1,
    );
    render();
  };

  mainCalendarMonthAnimating = true;

  try {
    if (animate === "swipe") {
      await animateSwipeMonthTransition(
        calendarGrid,
        direction,
        updateMonth,
      );
      return;
    }

    if (!animate) {
      updateMonth();
      return;
    }

    await animateMonthTransition(
      calendarGrid,
      direction,
      updateMonth,
    );
  } finally {
    mainCalendarMonthAnimating = false;
  }
}

async function changeDatePickerMonth(
  direction,
  { animate = true } = {},
) {
  if (datePickerMonthAnimating) {
    return;
  }

  const updateMonth = () => {
    datePickerVisibleMonth = new Date(
      datePickerVisibleMonth.getFullYear(),
      datePickerVisibleMonth.getMonth() + direction,
      1,
    );
    renderDatePicker();
  };

  datePickerMonthAnimating = true;

  try {
    if (animate === "swipe") {
      await animateSwipeMonthTransition(
        datePickerGrid,
        direction,
        updateMonth,
      );
      return;
    }

    if (!animate) {
      updateMonth();
      return;
    }

    await animateMonthTransition(
      datePickerGrid,
      direction,
      updateMonth,
    );
  } finally {
    datePickerMonthAnimating = false;
  }
}

function prepareCalendarAnimationClone(grid) {
  const clone = grid.cloneNode(true);

  clone.removeAttribute("id");
  clone.setAttribute("aria-hidden", "true");
  clone.querySelectorAll("[id]").forEach((element) => {
    element.removeAttribute("id");
  });
  clone.querySelectorAll("button, input, select, textarea, a").forEach(
    (element) => {
      element.setAttribute("tabindex", "-1");
    },
  );

  return clone;
}

async function animateSwipeMonthTransition(
  grid,
  direction,
  updateMonth,
) {
  const reduceMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (
    reduceMotion ||
    typeof Element.prototype.animate !== "function"
  ) {
    updateMonth();
    return;
  }

  const rect = grid.getBoundingClientRect();

  if (rect.width <= 0 || rect.height <= 0) {
    updateMonth();
    return;
  }

  const computedStyle = window.getComputedStyle(grid);
  const ghost = prepareCalendarAnimationClone(grid);
  const viewport = document.createElement("div");

  viewport.className = "calendar-swipe-animation-viewport";
  viewport.setAttribute("aria-hidden", "true");
  Object.assign(viewport.style, {
    position: "fixed",
    left: `${rect.left}px`,
    top: `${rect.top}px`,
    width: `${rect.width}px`,
    height: `${rect.height}px`,
    overflow: "hidden",
    pointerEvents: "none",
    zIndex: "2",
    contain: "layout paint style",
  });

  Object.assign(ghost.style, {
    position: "absolute",
    inset: "0",
    width: "100%",
    height: "100%",
    margin: "0",
    boxSizing: "border-box",
    pointerEvents: "none",
    backgroundColor:
      computedStyle.backgroundColor === "rgba(0, 0, 0, 0)"
        ? "var(--surface, #ffffff)"
        : computedStyle.backgroundColor,
  });

  viewport.appendChild(ghost);
  document.body.appendChild(viewport);

  /*
   * 실제 달력은 먼저 새 달로 즉시 교체해 터치 가능한 상태로 둡니다.
   * 화면 위에는 pointer-events:none인 이전 달 복제본만 움직이므로,
   * 애니메이션 중에도 첫 번째 터치가 실제 새 달력에 바로 전달됩니다.
   */
  updateMonth();

  const exitDistance = direction > 0 ? "-100%" : "100%";
  const animation = ghost.animate(
    [
      { transform: "translateX(0)", opacity: 1 },
      { transform: `translateX(${exitDistance})`, opacity: 0.12 },
    ],
    {
      duration: 240,
      easing: "cubic-bezier(0.22, 1, 0.36, 1)",
      fill: "forwards",
    },
  );

  try {
    await animation.finished;
  } catch (error) {
    // 화면 전환이나 렌더링으로 애니메이션이 취소되어도 정리합니다.
  } finally {
    animation.cancel();
    viewport.remove();
  }
}

async function animateMonthTransition(
  grid,
  direction,
  updateMonth,
) {
  const reduceMotion = window.matchMedia(
    "(prefers-reduced-motion: reduce)",
  ).matches;

  if (reduceMotion || typeof grid.animate !== "function") {
    updateMonth();
    return;
  }

  const exitDistance = direction > 0 ? "-32%" : "32%";
  const enterDistance = direction > 0 ? "32%" : "-32%";

  const exitAnimation = grid.animate(
    [
      { transform: "translateX(0)", opacity: 1 },
      { transform: `translateX(${exitDistance})`, opacity: 0 },
    ],
    {
      duration: 130,
      easing: "ease-in",
      fill: "forwards",
    },
  );

  await exitAnimation.finished.catch(() => {});
  exitAnimation.cancel();

  updateMonth();

  const enterAnimation = grid.animate(
    [
      { transform: `translateX(${enterDistance})`, opacity: 0 },
      { transform: "translateX(0)", opacity: 1 },
    ],
    {
      duration: 190,
      easing: "cubic-bezier(0.22, 1, 0.36, 1)",
    },
  );

  await enterAnimation.finished.catch(() => {});
  enterAnimation.cancel();
  grid.style.removeProperty("transform");
  grid.style.removeProperty("opacity");
}

function armCalendarSwipeTapRecovery() {
  calendarSwipeTapRecoveryUntil =
    performance.now() + CALENDAR_SWIPE_TAP_RECOVERY_MS;
  calendarSwipeTapCandidate = null;
  calendarSwipeNativeClickBlock = null;
}

function clearCalendarSwipeTapCandidate({ keepRecovery = false } = {}) {
  calendarSwipeTapCandidate = null;

  if (!keepRecovery) {
    calendarSwipeTapRecoveryUntil = 0;
  }
}

function getCalendarSwipeActivationTarget(candidate) {
  const pointTarget = document.elementFromPoint(
    candidate.endX,
    candidate.endY,
  );
  const fallbackTarget =
    candidate.target instanceof Element &&
    candidate.target.isConnected
      ? candidate.target
      : null;
  /*
   * 급여 페이지는 전환 중 버튼이 세로로 움직이므로, 전환이 끝난 뒤
   * 같은 좌표를 다시 찾으면 다른 요소가 선택될 수 있습니다.
   * 실제로 누르기 시작한 버튼이 그대로 연결돼 있으면 그 버튼을 우선합니다.
   * 달력은 월 변경 때 날짜 요소가 교체되므로 기존 좌표 탐색을 유지합니다.
   */
  const element =
    candidate.startedInSalaryPager &&
    fallbackTarget instanceof Element
      ? fallbackTarget
      : pointTarget instanceof Element
        ? pointTarget
        : fallbackTarget;

  if (!(element instanceof Element)) {
    return null;
  }

  return (
    element.closest(
      "button, a[href], input, select, textarea, [role='button']",
    ) || element
  );
}

function activateRecoveredCalendarSwipeTap(candidate) {
  const target = getCalendarSwipeActivationTarget(candidate);

  if (!(target instanceof Element)) {
    return;
  }

  calendarSwipeSyntheticClickInProgress = true;

  try {
    if (typeof target.click === "function") {
      target.click();
      return;
    }

    target.dispatchEvent(
      new MouseEvent("click", {
        bubbles: true,
        cancelable: true,
        composed: true,
        view: window,
        clientX: candidate.endX,
        clientY: candidate.endY,
      }),
    );
  } finally {
    calendarSwipeSyntheticClickInProgress = false;
  }
}

function replayCalendarSwipeTapWhenReady(
  candidate,
  startedAt = performance.now(),
) {
  const mainTransitionActive =
    candidate.startedInMainCalendar &&
    mainCalendarMonthAnimating;
  const pickerTransitionActive =
    candidate.startedInDatePicker &&
    datePickerMonthAnimating;
  const salaryTransitionActive =
    candidate.startedInSalaryPager &&
    salaryMobilePageTransitioning;

  if (
    (
      mainTransitionActive ||
      pickerTransitionActive ||
      salaryTransitionActive
    ) &&
    performance.now() - startedAt < 900
  ) {
    window.requestAnimationFrame(() => {
      replayCalendarSwipeTapWhenReady(candidate, startedAt);
    });
    return;
  }

  activateRecoveredCalendarSwipeTap(candidate);
}

document.addEventListener(
  "pointerdown",
  (event) => {
    if (
      event.pointerType !== "touch" &&
      event.pointerType !== "pen"
    ) {
      return;
    }

    /*
     * 급여 페이지의 새 실제 터치는 이전 스와이프/합성 click 차단보다
     * 항상 우선합니다. 이 값을 여기서 먼저 해제해야 스와이프 직후
     * 첫 번째 터치가 이전 동작의 차단 플래그에 먹히지 않습니다.
     */
    if (
      currentAppPage === "salary" &&
      isSalaryMobilePager()
    ) {
      salaryMonthTouchClickBlocked = false;
      salarySettingsTouchClickBlocked = false;
    }

    /*
     * 새로운 실제 손가락 동작이 시작되면 이전 동작의 지연 click 차단은
     * 더 이상 필요하지 않습니다. 이렇게 해야 빠른 연속 터치도 막히지 않습니다.
     */
    calendarSwipeNativeClickBlock = null;

    if (performance.now() > calendarSwipeTapRecoveryUntil) {
      return;
    }

    if (
      currentAppPage === "salary" &&
      isSalaryMobilePager() &&
      event.target instanceof Element &&
      event.target.closest(
        "input, select, textarea, label, [contenteditable='true']",
      )
    ) {
      /*
       * 입력 컨트롤은 브라우저의 실제 터치/포커스를 그대로 사용합니다.
       * synthetic click으로 바꾸면 첫 터치에서 키보드가 안 뜨는 문제가
       * 생길 수 있습니다.
       */
      calendarSwipeTapCandidate = null;
      return;
    }

    calendarSwipeTapCandidate = {
      pointerId: event.pointerId,
      startX: event.clientX,
      startY: event.clientY,
      endX: event.clientX,
      endY: event.clientY,
      target: event.target,
      startedInMainCalendar:
        event.target instanceof Node &&
        calendarGrid.contains(event.target),
      startedInDatePicker:
        event.target instanceof Node &&
        datePickerGrid.contains(event.target),
      startedInSalaryPager:
        currentAppPage === "salary" &&
        isSalaryMobilePager(),
      moved: false,
    };
  },
  true,
);

document.addEventListener(
  "pointermove",
  (event) => {
    const candidate = calendarSwipeTapCandidate;

    if (!candidate || candidate.pointerId !== event.pointerId) {
      return;
    }

    candidate.endX = event.clientX;
    candidate.endY = event.clientY;

    if (
      Math.abs(event.clientX - candidate.startX) > 14 ||
      Math.abs(event.clientY - candidate.startY) > 14
    ) {
      candidate.moved = true;
    }
  },
  true,
);

document.addEventListener(
  "pointerup",
  (event) => {
    const candidate = calendarSwipeTapCandidate;

    if (!candidate || candidate.pointerId !== event.pointerId) {
      return;
    }

    candidate.endX = event.clientX;
    candidate.endY = event.clientY;

    if (candidate.moved) {
      clearCalendarSwipeTapCandidate({ keepRecovery: true });
      return;
    }

    /*
     * 스와이프 뒤 첫 탭은 브라우저의 click 생성 여부에 맡기지 않고
     * pointerup에서 직접 한 번만 처리합니다. 실제 click은 아래 차단기가
     * 같은 좌표의 지연 click 한 번만 막아 중복 실행을 방지합니다.
     */
    event.preventDefault();
    event.stopImmediatePropagation();

    calendarSwipeNativeClickBlock = {
      x: candidate.endX,
      y: candidate.endY,
      expiresAt: performance.now() + 700,
    };

    clearCalendarSwipeTapCandidate();
    replayCalendarSwipeTapWhenReady(candidate);
  },
  true,
);

document.addEventListener(
  "click",
  (event) => {
    if (calendarSwipeSyntheticClickInProgress) {
      return;
    }

    const block = calendarSwipeNativeClickBlock;

    if (!block) {
      return;
    }

    if (performance.now() > block.expiresAt) {
      calendarSwipeNativeClickBlock = null;
      return;
    }

    const isSameTap =
      Math.abs(event.clientX - block.x) <= 28 &&
      Math.abs(event.clientY - block.y) <= 28;

    if (!isSameTap) {
      return;
    }

    calendarSwipeNativeClickBlock = null;
    event.preventDefault();
    event.stopImmediatePropagation();
  },
  true,
);

["pointercancel", "lostpointercapture"].forEach((eventName) => {
  document.addEventListener(
    eventName,
    (event) => {
      if (
        calendarSwipeTapCandidate?.pointerId === event.pointerId
      ) {
        clearCalendarSwipeTapCandidate({ keepRecovery: true });
      }
    },
    true,
  );
});

function attachHorizontalMonthSwipe(element, onSwipe) {
  let activePointerId = null;
  let startX = 0;
  let startY = 0;

  element.addEventListener("pointerdown", (event) => {
    if (
      !event.isPrimary ||
      (event.pointerType === "mouse" && event.button !== 0)
    ) {
      return;
    }

    activePointerId = event.pointerId;
    startX = event.clientX;
    startY = event.clientY;
  });

  element.addEventListener("pointerup", (event) => {
    if (event.pointerId !== activePointerId) {
      return;
    }

    activePointerId = null;

    const deltaX = event.clientX - startX;
    const deltaY = event.clientY - startY;

    if (
      Math.abs(deltaX) < 48 ||
      Math.abs(deltaX) <= Math.abs(deltaY)
    ) {
      return;
    }

    armCalendarSwipeTapRecovery();
    onSwipe(deltaX < 0 ? 1 : -1);
  });

  element.addEventListener("pointercancel", () => {
    activePointerId = null;
  });
}

function renderDatePicker() {
  renderCalendarWeekdayHeaders();

  const year = datePickerVisibleMonth.getFullYear();
  const month = datePickerVisibleMonth.getMonth();
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDayPosition = getCalendarFirstDayPosition(
    new Date(year, month, 1),
  );
  const selectedDateKey = datePickerTargetInput?.value || "";
  const today = new Date();
  const todayDateKey = createDateKey(
    today.getFullYear(),
    today.getMonth(),
    today.getDate(),
  );

  datePickerTitle.textContent = `${year}년 ${month + 1}월`;
  datePickerGrid.innerHTML = "";

  for (let cellIndex = 0; cellIndex < 42; cellIndex += 1) {
    const dayNumber = cellIndex - firstDayPosition + 1;

    if (dayNumber < 1 || dayNumber > daysInMonth) {
      const emptyCell = document.createElement("span");

      emptyCell.className = "date-picker-day empty";
      emptyCell.setAttribute("aria-hidden", "true");
      datePickerGrid.appendChild(emptyCell);
      continue;
    }

    const date = new Date(year, month, dayNumber);
    const dateKey = createDateKey(year, month, dayNumber);
    const holidayName = getHolidayName(dateKey);
    const workType = getWorkType(records[dateKey]);
    const workTypeLabel = workType?.label || "";
    const dayButton = document.createElement("button");

    dayButton.type = "button";
    dayButton.className = "date-picker-day";
    dayButton.innerHTML = `
      <span class="date-picker-day-number">${dayNumber}</span>
      ${
        holidayName
          ? `<span class="date-picker-holiday-name">${escapeHtml(holidayName)}</span>`
          : ""
      }
      ${
        workType
          ? `<span class="date-picker-work-name type-${workType.id}">${escapeHtml(workTypeLabel)}</span>`
          : ""
      }
    `;
    dayButton.setAttribute(
      "aria-label",
      `${year}년 ${month + 1}월 ${dayNumber}일${holidayName ? ` ${holidayName}` : ""}${workTypeLabel ? ` ${workTypeLabel}` : ""} 선택`,
    );

    if (date.getDay() === 6) {
      dayButton.classList.add("saturday");
    }

    if (date.getDay() === 0) {
      dayButton.classList.add("sunday");
    }

    if (holidayName) {
      dayButton.classList.add("holiday");
      dayButton.title = holidayName;
    }

    if (workType) {
      dayButton.classList.add("has-work-record");
    }

    if (dateKey === todayDateKey) {
      dayButton.classList.add("today");
    }

    if (dateKey === selectedDateKey) {
      dayButton.classList.add("selected");
      dayButton.setAttribute("aria-current", "date");
    }

    dayButton.addEventListener("click", () => {
      selectDatePickerDate(dateKey);
    });

    datePickerGrid.appendChild(dayButton);
  }
}

function selectDatePickerDate(dateKey) {
  if (!datePickerTargetInput) {
    return;
  }

  datePickerTargetInput.value = dateKey;
  saveWeeklyDateRangeFromInputs();
  render52HourCalculator();
  closeDatePicker();
}

function isMobilePagerMode() {
  return (
    (mobilePagerMedia.matches || mobilePagerTestMode) &&
    mobilePages.length > 0 &&
    currentAppPage === "attendance"
  );
}

function syncMobilePagerMode() {
  const isMobile =
    isMobilePagerMode() &&
    currentAppPage === "attendance";

  mobilePageAnimations.forEach((animation) => {
    animation.cancel();
  });

  mobilePageAnimations = [];
  mobilePageAnimating = false;

  document.documentElement.classList.toggle(
    "mobile-pager-enabled",
    isMobile,
  );

  mobilePages.forEach((page, index) => {
    const isActive = index === mobilePageIndex;

    page.classList.remove("mobile-page-transitioning");
    page.classList.toggle(
      "mobile-page-active",
      isMobile && isActive,
    );

    if (isMobile) {
      page.inert = !isActive;
      page.setAttribute("aria-hidden", String(!isActive));
    } else {
      page.inert = false;
      page.removeAttribute("aria-hidden");
    }
  });

  updateMobilePageButtons();

  if (isMobile) {
    initializeBackExitGuard();
  }
}

function setMobilePage(nextIndex, requestedDirection = 0) {
  if (!isMobilePagerMode() || mobilePageAnimating) {
    return;
  }

  const pageCount = mobilePages.length;
  const normalizedIndex = Math.max(
    0,
    Math.min(nextIndex, pageCount - 1),
  );

  if (normalizedIndex === mobilePageIndex) {
    return;
  }

  const direction =
    requestedDirection ||
    (normalizedIndex > mobilePageIndex ? 1 : -1);

  const currentPage = mobilePages[mobilePageIndex];
  const nextPage = mobilePages[normalizedIndex];
  const outgoingOffset = direction > 0 ? "-100%" : "100%";
  const incomingOffset = direction > 0 ? "100%" : "-100%";

  mobilePageAnimating = true;
  mobilePageIndex = normalizedIndex;

  nextPage.scrollTop = 0;
  nextPage.inert = false;
  nextPage.setAttribute("aria-hidden", "false");
  nextPage.classList.add("mobile-page-transitioning");

  currentPage.classList.add("mobile-page-transitioning");
  updateMobilePageButtons();

  if (typeof nextPage.animate !== "function") {
    finishMobilePageTransition(currentPage, nextPage);
    return;
  }

  const animationOptions = {
    duration: 330,
    easing: "cubic-bezier(0.22, 1, 0.36, 1)",
    fill: "both",
  };

  mobilePageAnimations = [
    currentPage.animate(
      [
        { transform: "translateY(0)" },
        { transform: `translateY(${outgoingOffset})` },
      ],
      animationOptions,
    ),
    nextPage.animate(
      [
        { transform: `translateY(${incomingOffset})` },
        { transform: "translateY(0)" },
      ],
      animationOptions,
    ),
  ];

  Promise.allSettled(
    mobilePageAnimations.map((animation) => animation.finished),
  ).then(() => {
    if (
      !isMobilePagerMode() ||
      mobilePageIndex !== normalizedIndex
    ) {
      return;
    }

    finishMobilePageTransition(currentPage, nextPage);
  });
}

function finishMobilePageTransition(currentPage, nextPage) {
  currentPage.classList.remove(
    "mobile-page-active",
    "mobile-page-transitioning",
  );
  currentPage.inert = true;
  currentPage.setAttribute("aria-hidden", "true");

  nextPage.classList.remove("mobile-page-transitioning");
  nextPage.classList.add("mobile-page-active");
  nextPage.inert = false;
  nextPage.setAttribute("aria-hidden", "false");

  mobilePageAnimations = [];
  mobilePageAnimating = false;
}

function changeMobilePage(direction) {
  setMobilePage(mobilePageIndex + direction, direction);
}

function updateMobilePageButtons() {
  mobilePageButtons.forEach((button, index) => {
    const isActive = index === mobilePageIndex;

    button.classList.toggle("active", isActive);
    button.setAttribute("aria-current", String(isActive));
  });
}

function isMobilePageAtTop(page) {
  return page.scrollTop <= 2;
}

function isMobilePageAtBottom(page) {
  return page.scrollTop + page.clientHeight >= page.scrollHeight - 2;
}

function initializeBackExitGuard() {
  if (!shouldUseBackExitGuard()) {
    return;
  }

  if (!backExitGuardInitialized) {
    backExitGuardInitialized = true;
    window.addEventListener("pageshow", resetBackExitState);
    window.addEventListener("focus", resetBackExitState);
    window.addEventListener("pagehide", prepareBackExitForNextLaunch);
    document.addEventListener(
      "visibilitychange",
      handleAppVisibilityChange,
    );
  }

  ensureBackExitPopstateListener();
  ensureAppCloseWatcher();
  resetBackExitState();
}

function ensureAppCloseWatcher() {
  if (!shouldUseBackExitGuard() || appCloseWatcher) {
    return;
  }

  if (!supportsAppCloseWatcher()) {
    document.documentElement.dataset.backExitGuard = "history";
    return;
  }

  appCloseWatcher = new window.CloseWatcher();
  appCloseWatcher.addEventListener(
    "close",
    handleAppCloseRequest,
    { once: true },
  );
  document.documentElement.dataset.backExitGuard = "close-watcher";
}

function supportsAppCloseWatcher() {
  return typeof window.CloseWatcher === "function";
}

function installBackExitTestHook() {
  if (!mobilePagerTestMode || document.querySelector("#backExitTestButton")) {
    return;
  }

  const testButton = document.createElement("button");
  testButton.id = "backExitTestButton";
  testButton.type = "button";
  testButton.textContent = "back exit test";
  testButton.style.cssText =
    "position:fixed;left:0;top:0;width:2px;height:2px;opacity:0.001;z-index:9999;";
  testButton.addEventListener("click", () => {
    if (appCloseWatcher) {
      appCloseWatcher.requestClose();
    } else {
      handleAppBackNavigation();
    }
  });
  document.body.appendChild(testButton);
}

function handleAppCloseRequest() {
  appCloseWatcher = null;

  if (navigationDrawer.classList.contains("open")) {
    closeNavigationDrawer();
    resetBackExitState();
    return;
  }

  if (!salaryYearPicker.hidden) {
    closeSalaryYearPicker();
    resetBackExitState();
    return;
  }

  if (!annualLeaveYearPicker.hidden) {
    closeAnnualLeaveYearPicker();
    resetBackExitState();
    return;
  }

  if (workModal.classList.contains("open")) {
    closeModal();
    resetBackExitState();
    return;
  }

  if (monthPickerModal.classList.contains("open")) {
    closeMonthPicker();
    resetBackExitState();
    return;
  }

  if (datePickerModal.classList.contains("open")) {
    closeDatePicker();
    resetBackExitState();
    return;
  }

  if (!exitBackReady) {
    // 첫 번째 Android 뒤로가기는 CloseWatcher가 소비한다.
    // 안내가 보이는 동안에는 watcher를 만들지 않아 두 번째 요청을
    // Android의 기본 종료 동작으로 그대로 전달한다.
    showExitToast();
    return;
  }

  completeAppExit(true);
}

function ensureBackExitPopstateListener() {
  if (backExitPopstateAttached) {
    return;
  }

  window.addEventListener("popstate", handleAppBackNavigation);
  backExitPopstateAttached = true;
}

function shouldUseBackExitGuard() {
  return (
    isMobilePagerMode() ||
    window.matchMedia("(display-mode: standalone)").matches ||
    window.navigator.standalone === true
  );
}

function handleAppVisibilityChange() {
  if (document.visibilityState === "hidden") {
    prepareBackExitForNextLaunch();
    return;
  }

  resetBackExitState();
}

function prepareBackExitForNextLaunch() {
  if (!shouldUseBackExitGuard()) {
    return;
  }

  allowAppExitNavigation = false;
  exitBackReady = false;
  window.clearTimeout(exitToastTimer);
  hideExitToast();
  ensureBackExitPopstateListener();
  ensureAppCloseWatcher();
}

function resetBackExitState() {
  if (!shouldUseBackExitGuard()) {
    return;
  }

  allowAppExitNavigation = false;
  exitBackReady = false;
  window.clearTimeout(exitToastTimer);
  hideExitToast();
  ensureBackExitPopstateListener();
  ensureAppCloseWatcher();

  if (supportsAppCloseWatcher()) {
    const currentState =
      window.history.state &&
      typeof window.history.state === "object"
        ? { ...window.history.state }
        : {};

    delete currentState.catAttendanceAppBase;
    delete currentState.catAttendanceExitGuard;
    window.history.replaceState(
      currentState,
      "",
      window.location.href,
    );
    return;
  }

  const currentState =
    window.history.state &&
    typeof window.history.state === "object"
      ? window.history.state
      : {};

  // 설치형 앱을 다시 실행하면 이전 실행의 history.state만 복원되고
  // 실제 이전 항목은 없는 경우가 있다. 새 실행에서는 현재 항목을
  // 기준점으로 다시 만들고 보호 항목을 하나 추가해야 첫 뒤로가기를
  // 항상 안내 문구로 받을 수 있다.
  if (!backExitGuardArmedThisSession) {
    window.history.replaceState(
      {
        ...currentState,
        catAttendanceAppBase: true,
        catAttendanceExitGuard: false,
      },
      "",
      window.location.href,
    );

    backExitGuardArmedThisSession = true;
    restoreBackExitGuard();
    return;
  }

  if (currentState.catAttendanceExitGuard) {
    return;
  }

  if (!currentState.catAttendanceAppBase) {
    window.history.replaceState(
      {
        ...currentState,
        catAttendanceAppBase: true,
      },
      "",
      window.location.href,
    );
  }

  restoreBackExitGuard();
}

function handleAppBackNavigation() {
  if (allowAppExitNavigation) {
    return;
  }

  if (navigationDrawer.classList.contains("open")) {
    closeNavigationDrawer();
    resetBackExitState();
    return;
  }

  if (!salaryYearPicker.hidden) {
    closeSalaryYearPicker();
    resetBackExitState();
    return;
  }

  if (!annualLeaveYearPicker.hidden) {
    closeAnnualLeaveYearPicker();
    resetBackExitState();
    return;
  }

  if (workModal.classList.contains("open")) {
    closeModal();
    resetBackExitState();
    return;
  }

  if (monthPickerModal.classList.contains("open")) {
    closeMonthPicker();
    resetBackExitState();
    return;
  }

  if (datePickerModal.classList.contains("open")) {
    closeDatePicker();
    resetBackExitState();
    return;
  }

  if (!exitBackReady) {
    if (supportsAppCloseWatcher() && appCloseWatcher) {
      appCloseWatcher.destroy();
      appCloseWatcher = null;
    }

    showExitToast();

    if (!supportsAppCloseWatcher()) {
      restoreBackExitGuard();
    }
    return;
  }

  completeAppExit(false);
}

function completeAppExit(fromCloseWatcher) {
  exitBackReady = false;
  allowAppExitNavigation = true;
  window.clearTimeout(exitToastTimer);
  hideExitToast();

  if (appCloseWatcher) {
    appCloseWatcher.destroy();
    appCloseWatcher = null;
  }

  window.removeEventListener("popstate", handleAppBackNavigation);
  backExitPopstateAttached = false;

  if (mobilePagerTestMode) {
    resetBackExitState();
    return;
  }

  window.setTimeout(() => {
    if (fromCloseWatcher) {
      window.history.go(-2);
    } else {
      window.history.back();
    }

    window.setTimeout(() => {
      window.close();

      window.setTimeout(() => {
        prepareBackExitForNextLaunch();
      }, 250);
    }, 120);
  }, 0);
}

function restoreBackExitGuard() {
  const currentState = window.history.state;

  if (currentState?.catAttendanceExitGuard) {
    return;
  }

  window.history.pushState(
    { catAttendanceExitGuard: true },
    "",
    window.location.href,
  );
}

function showExitToast() {
  exitBackReady = true;
  window.clearTimeout(exitToastTimer);

  exitToast.classList.add("show");
  exitToast.setAttribute("aria-hidden", "false");

  exitToastTimer = window.setTimeout(() => {
    exitBackReady = false;
    hideExitToast();
    ensureAppCloseWatcher();
  }, 2200);
}

function hideExitToast() {
  exitToast.classList.remove("show");
  exitToast.setAttribute("aria-hidden", "true");
}

function resetExitPromptAfterUserAction(event) {
  if (!exitBackReady || allowAppExitNavigation) {
    return;
  }

  if (
    event?.type === "keydown" &&
    (event.key === "BrowserBack" ||
      (event.altKey && event.key === "ArrowLeft"))
  ) {
    return;
  }

  resetBackExitState();
}

["pointerdown", "input", "change"].forEach((eventName) => {
  document.addEventListener(
    eventName,
    resetExitPromptAfterUserAction,
    true,
  );
});

document.addEventListener(
  "keydown",
  resetExitPromptAfterUserAction,
  true,
);

window.addEventListener(
  "scroll",
  resetExitPromptAfterUserAction,
  { passive: true, capture: true },
);

function setSummarySlide(nextIndex) {
  const slideCount = summarySlides.length;

  summarySlideIndex =
    ((nextIndex % slideCount) + slideCount) % slideCount;

  summaryTrack.style.transform =
    `translateX(-${summarySlideIndex * 100}%)`;

  summarySlides.forEach((slide, index) => {
    slide.setAttribute(
      "aria-hidden",
      String(index !== summarySlideIndex),
    );
  });

  summaryPageButtons.forEach((button, index) => {
    const isActive = index === summarySlideIndex;

    button.classList.toggle("active", isActive);
    button.setAttribute("aria-current", String(isActive));
  });
}

function changeSummarySlide(direction) {
  setSummarySlide(summarySlideIndex + direction);
}

function render() {
  renderCalendar();
  syncWeeklyDateRangeInputs();
  renderSummary();
  syncSalaryInputs();
  renderBonusEditor();
  renderSalary();
}

function renderCalendar() {
  renderCalendarWeekdayHeaders();

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();

  monthTitle.textContent = `${year}년 ${month + 1}월`;
  calendarGrid.innerHTML = "";

  const firstDate = new Date(year, month, 1);
  const daysInMonth = new Date(year, month + 1, 0).getDate();

  const firstDayPosition = getCalendarFirstDayPosition(firstDate);
  const today = new Date();

  for (let cellIndex = 0; cellIndex < 42; cellIndex += 1) {
    const dayNumber = cellIndex - firstDayPosition + 1;

    if (dayNumber < 1 || dayNumber > daysInMonth) {
      const emptyCell = document.createElement("div");

      emptyCell.className = "day-cell empty";
      calendarGrid.appendChild(emptyCell);

      continue;
    }

    const date = new Date(year, month, dayNumber);
    const dateKey = createDateKey(year, month, dayNumber);
    const holidayName = getHolidayName(dateKey);

    const workRecord = records[dateKey];
    const workType = getWorkType(workRecord);

    const dayButton = document.createElement("button");

    dayButton.type = "button";
    dayButton.className = "day-cell";

    if (
      today.getFullYear() === year &&
      today.getMonth() === month &&
      today.getDate() === dayNumber
    ) {
      dayButton.classList.add("today");
    }

    if (date.getDay() === 0) {
      dayButton.classList.add("sunday-cell");
    }

    if (date.getDay() === 6) {
      dayButton.classList.add("saturday-cell");
    }

    if (holidayName) {
      dayButton.classList.add("holiday-cell");
      dayButton.title = holidayName;
      dayButton.setAttribute(
        "aria-label",
        `${year}년 ${month + 1}월 ${dayNumber}일 ${holidayName}`,
      );
    }

    if (workType) {
      dayButton.classList.add(`type-${workType.id}`);
    }

    dayButton.innerHTML = `
      <span class="day-number">${dayNumber}</span>

      ${
        holidayName
          ? `<span class="holiday-name">${holidayName}</span>`
          : ""
      }

      ${
        workType
          ? `<span class="work-badge">${escapeHtml(workType.label)}</span>`
          : `<span class="empty-record">근무 선택</span>`
      }
    `;

    dayButton.addEventListener("click", () => {
      openModal(dateKey, year, month, dayNumber);
    });

    calendarGrid.appendChild(dayButton);
  }
}

function renderSummary() {
  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();
  const stats = calculateMonthStats();

  recordedDays.textContent = formatUnit(stats.recordedDays, "일");

  summaryGrid.innerHTML = SUMMARY_WORK_TYPES.map(
    (workType) => `
      <div class="summary-item">
        <span class="summary-dot type-${workType.id}"></span>

        <span class="summary-label">
          ${workType.label}
        </span>

        <strong>${formatUnit(stats.counts[workType.id], "일")}</strong>
      </div>
    `,
  ).join("");

  const daysInMonth = new Date(
    year,
    month + 1,
    0,
  ).getDate();

  const sundayCount = countSundaysInMonth(year, month);
  const basePayDays = daysInMonth - sundayCount;
  const basePayHours = basePayDays * 8;

  const workTotals = [
    [
      "근무기록 일수",
      formatUnit(formatNumber(stats.regularDays), "일"),
    ],
    ["기본급 적용일수", formatUnit(basePayDays, "일")],
    ["일요일 수", formatUnit(sundayCount, "일")],
    ["기본급 시간", formatUnit(basePayHours, "시간")],
    [
      "연장시간",
      formatUnit(formatNumber(stats.overtimeHours), "시간"),
    ],
    [
      "심야시간",
      formatUnit(formatNumber(stats.nightHours), "시간"),
    ],
    [
      "철야시간",
      formatUnit(formatNumber(stats.overnightHours), "시간"),
    ],
    [
      "휴일시간",
      formatUnit(formatNumber(stats.holidayHours), "시간"),
    ],
    [
      "휴연시간",
      formatUnit(
        formatNumber(stats.holidayOvertimeHours),
        "시간",
      ),
    ],
  ];

  workTotalsGrid.innerHTML = workTotals
    .map(
      ([label, value]) => `
        <div class="work-total-row">
          <span>${label}</span>
          <strong>${value}</strong>
        </div>
      `,
    )
    .join("");

  render52HourCalculator();
  renderAnnualLeaveSummary();
  setSummarySlide(summarySlideIndex);
}

function render52HourCalculator() {
  const startDate = parseDateInputValue(
    weeklyStartDateInput.value,
  );
  const endDate = parseDateInputValue(
    weeklyEndDateInput.value,
  );

  if (!startDate || !endDate) {
    weeklyAverageResult.textContent =
      "시작일과 종료일을 선택해 주세요.";
    weeklyAverageResult.classList.remove("error");
    weeklyAverageResult.classList.remove("has-result");
    return;
  }

  if (startDate.getTime() > endDate.getTime()) {
    weeklyAverageResult.textContent =
      "종료일은 시작일보다 빠를 수 없습니다.";
    weeklyAverageResult.classList.add("error");
    weeklyAverageResult.classList.remove("has-result");
    return;
  }

  const {
    averageHours,
    dayCount,
    totalWorkHours,
  } = calculate52HourAverage(startDate, endDate);

  const fullWeeks = Math.floor(dayCount / 7);
  const remainingDays = dayCount % 7;

  weeklyAverageResult.innerHTML = `
    <div class="weekly-result-summary">
      <div class="weekly-result-grid">
        <div class="weekly-result-item weekly-duration">
          <strong>${formatUnit(fullWeeks, "주")} ${formatUnit(remainingDays, "일")}</strong>
          <span>동안</span>
        </div>

        <div class="weekly-result-item">
          <span>총 근무시간</span>
          <strong>${formatUnit(formatTotalWorkHours(totalWorkHours), "시간")}</strong>
        </div>

        <div class="weekly-result-item">
          <span>평균 근무시간</span>
          <strong>${formatUnit(formatAverageHours(averageHours), "시간")}</strong>
        </div>
      </div>
    </div>
  `;
  weeklyAverageResult.classList.remove("error");
  weeklyAverageResult.classList.add("has-result");
}

function renderAnnualLeaveSummary(syncInput = true) {
  const year = annualLeaveSelectedYear;
  const accruedLeave = getAnnualLeaveForYear(year);
  const usedLeave = countUsedAnnualLeave(year);
  const remainingLeave = accruedLeave - usedLeave;

  annualLeaveYearButton.textContent = `${year}년`;

  if (syncInput) {
    accruedAnnualLeaveInput.value =
      accruedLeave === 0 ? "" : String(accruedLeave);
  }

  usedAnnualLeaveOutput.textContent =
    formatUnit(formatAnnualLeaveDays(usedLeave), "일");
  remainingAnnualLeaveOutput.textContent =
    formatUnit(formatAnnualLeaveDays(remainingLeave), "일");
  remainingAnnualLeaveOutput.classList.toggle(
    "negative",
    remainingLeave < 0,
  );

  renderAnnualLeaveHistory(year);
}

function renderAnnualLeaveHistory(year) {
  const ranges = getAnnualLeaveRanges(year);

  if (ranges.length === 0) {
    annualLeaveHistoryBody.innerHTML = `
      <div class="annual-leave-history-empty">
        이 연도에 사용한 연차가 없습니다.
      </div>
    `;
    return;
  }

  annualLeaveHistoryBody.innerHTML = ranges
    .map((range) => {
      const rangeKey = getAnnualLeaveReasonKey(year, range.start);
      const reason = annualLeaveReasons[rangeKey] || "";

      return `
        <div class="annual-leave-history-row" role="row">
          <span class="annual-leave-date-cell" role="cell">
            ${formatAnnualLeaveHistoryDateButton(range.start)}
          </span>
          <span class="annual-leave-date-cell" role="cell">
            ${range.calendarDays === 1 ? "" : formatAnnualLeaveHistoryDateButton(range.end)}
          </span>
          <span class="annual-leave-days-cell" role="cell">${formatAnnualLeaveDays(range.leaveDays)}일</span>
          <label class="annual-leave-reason-cell" role="cell">
            <span class="sr-only">${formatAnnualLeaveHistoryDate(range.start)} 연차 사유</span>
            <input
              type="text"
              maxlength="120"
              autocomplete="off"
              placeholder="사유 입력"
              data-annual-leave-reason="${rangeKey}"
              value="${escapeHtml(reason)}"
            />
          </label>
        </div>
      `;
    })
    .join("");
}

function getAnnualLeaveRanges(year) {
  const yearPrefix = `${year}-`;
  const oneDay = 24 * 60 * 60 * 1000;

  const leaveDates = Object.entries(records)
    .map(([dateKey, workRecord]) => ({
      dateKey,
      usage: getAnnualLeaveUsage(workRecord),
    }))
    .filter(
      ({ dateKey, usage }) =>
        dateKey.startsWith(yearPrefix) && usage > 0,
    )
    .map(({ dateKey, usage }) => {
      const [dateYear, month, day] = dateKey.split("-").map(Number);
      return {
        dateKey,
        time: Date.UTC(dateYear, month - 1, day),
        month,
        day,
        usage,
      };
    })
    .sort((left, right) => left.time - right.time);

  return leaveDates.reduce((ranges, date) => {
    const currentRange = ranges[ranges.length - 1];

    if (!currentRange || date.time - currentRange.end.time !== oneDay) {
      ranges.push({
        start: date,
        end: date,
        calendarDays: 1,
        leaveDays: date.usage,
      });
      return ranges;
    }

    currentRange.end = date;
    currentRange.calendarDays += 1;
    currentRange.leaveDays += date.usage;
    return ranges;
  }, []);
}

function formatAnnualLeaveHistoryDate(date) {
  return `${date.month}월 ${date.day}일`;
}

function formatAnnualLeaveHistoryDateMarkup(date) {
  return `
    <span class="annual-leave-date-value">
      <span class="annual-leave-date-part">
        <span class="annual-leave-date-number">${date.month}</span><span>월</span>
      </span>
      <span class="annual-leave-date-part">
        <span class="annual-leave-date-number">${date.day}</span><span>일</span>
      </span>
    </span>
  `;
}

function formatAnnualLeaveHistoryDateButton(date) {
  return `
    <button
      class="annual-leave-date-button"
      type="button"
      data-annual-leave-date="${date.dateKey}"
      aria-label="${formatAnnualLeaveHistoryDate(date)} 근태관리 달력으로 이동"
    >
      ${formatAnnualLeaveHistoryDateMarkup(date)}
    </button>
  `;
}

function navigateToAnnualLeaveDate(dateKey) {
  const [year, month] = dateKey.split("-").map(Number);

  if (!Number.isInteger(year) || !Number.isInteger(month)) {
    return;
  }

  currentMonth = new Date(year, month - 1, 1);
  mobilePageIndex = 0;
  setAppPage("attendance");
  render();
  syncMobilePagerMode();
}

function getAnnualLeaveReasonKey(year, startDate) {
  return `${year}:${startDate.dateKey}`;
}

function getAnnualLeaveForYear(year) {
  const value = Number(annualLeaveByYear[String(year)]);

  return Number.isFinite(value) && value >= 0 ? value : 0;
}

function getAnnualLeaveUsage(workRecord) {
  const workTypeId = getWorkType(workRecord)?.id;

  if (workTypeId === "annualLeave") {
    return 1;
  }

  if (workTypeId === "halfAnnualLeave") {
    return 0.5;
  }

  return 0;
}

function countUsedAnnualLeave(year) {
  const yearPrefix = `${year}-`;

  return Object.entries(records).reduce(
    (count, [dateKey, workRecord]) => {
      if (!dateKey.startsWith(yearPrefix)) {
        return count;
      }

      return count + getAnnualLeaveUsage(workRecord);
    },
    0,
  );
}

function formatAnnualLeaveDays(value) {
  return new Intl.NumberFormat("ko-KR", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  }).format(value);
}

function sanitizeAnnualLeaveInput(value) {
  const normalizedValue = String(value)
    .replace(/,/g, ".")
    .replace(/[^0-9.]/g, "");
  const [integerPart = "", ...fractionParts] =
    normalizedValue.split(".");

  if (fractionParts.length === 0) {
    return integerPart;
  }

  const fractionPart = fractionParts.join("").slice(0, 1);
  const safeIntegerPart = integerPart || "0";

  return `${safeIntegerPart}.${fractionPart}`;
}

function calculate52HourAverage(startDate, endDate) {
  const millisecondsPerDay = 24 * 60 * 60 * 1000;
  const dayCount =
    Math.floor(
      (endDate.getTime() - startDate.getTime()) /
        millisecondsPerDay,
    ) + 1;

  let totalWorkHours = 0;

  for (
    let dateValue = startDate.getTime();
    dateValue <= endDate.getTime();
    dateValue += millisecondsPerDay
  ) {
    const date = new Date(dateValue);
    const dateKey = createDateKeyFromUtcDate(date);

    totalWorkHours += get52HourWorkHours(records[dateKey]);
  }

  const averageHours =
    totalWorkHours / (dayCount * 0.14285714285714);

  return {
    averageHours,
    dayCount,
    totalWorkHours,
  };
}

function get52HourWorkHours(workRecord) {
  const workType = getWorkType(workRecord);

  if (
    !workType ||
    workType.id === "annualLeave" ||
    workType.id === "halfAnnualLeave" ||
    workType.id === CUSTOM_WORK_TYPE.id
  ) {
    return 0;
  }

  return workType.label.endsWith("잔업") ? 10.5 : 8;
}

function parseDateInputValue(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return null;
  }

  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(Date.UTC(year, month - 1, day));

  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  return date;
}

function createDateKeyFromUtcDate(date) {
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  const day = String(date.getUTCDate()).padStart(2, "0");

  return `${year}-${month}-${day}`;
}


function formatTotalWorkHours(value) {
  return new Intl.NumberFormat("ko-KR", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 1,
  }).format(value);
}

function formatAverageHours(value) {
  return new Intl.NumberFormat("ko-KR", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  }).format(value);
}


function truncatePayrollToTen(value) {
  if (!Number.isFinite(value) || value <= 0) {
    return 0;
  }

  return Math.floor(value / 10) * 10;
}

function getVerifiedPayrollInsuranceForMonth(year, month) {
  /*
   * 실제 급여명세서로 검증한 개인 기준값.
   * 새 기준소득월액/보수월액이 확인되기 전까지 가장 최근 확정값을 유지한다.
   */
  if (year <= 2025) {
    return {
      pension: 202500,
      health: 180170,
    };
  }

  if (year === 2026 && month <= 5) {
    return {
      pension: 213750,
      health: 183020,
    };
  }

  return {
    pension: 231180,
    health: 202090,
  };
}

function calculatePayrollDeductions(year, month, totalPay) {
  if (!Number.isFinite(totalPay) || totalPay <= 0) {
    return {
      incomeTax: 0,
      localIncomeTax: 0,
      pension: 0,
      health: 0,
      employment: 0,
      employeeClub: 0,
      totalDeduction: 0,
      netPay: 0,
    };
  }

  const {
    pension,
    health,
  } = getVerifiedPayrollInsuranceForMonth(year, month);

  const annualizedPay = totalPay * 12;
  let rawIncomeTax;

  /*
   * 2026년 2월 실제 급여명세서로 검증한 구간.
   * 연환산 총급여가 3,000만원 초과~4,500만원 이하이면
   * 4,500만원 초과 구간과 다른 공제식을 사용한다.
   */
  if (
    annualizedPay > 30000000 &&
    annualizedPay <= 45000000
  ) {
    rawIncomeTax =
      totalPay * 0.129 -
      pension * 0.15 -
      308125;
  } else {
    let incomeTaxConstant;

    /*
     * 기존에 실제 명세서로 검증된 4,500만원 초과 구간은
     * 계산식을 그대로 유지한다.
     */
    if (annualizedPay <= 55000000) {
      incomeTaxConstant = 345625;
    } else if (annualizedPay >= 55060000) {
      incomeTaxConstant = 343125;
    } else {
      const transitionRatio =
        (annualizedPay - 55000000) / 60000;

      incomeTaxConstant =
        345625 - transitionRatio * 2500;
    }

    rawIncomeTax =
      totalPay * 0.1395 -
      pension * 0.15 -
      incomeTaxConstant;
  }

  const incomeTax = truncatePayrollToTen(
    rawIncomeTax,
  );

  const localIncomeTax = truncatePayrollToTen(
    incomeTax * 0.1,
  );

  const employment = truncatePayrollToTen(
    totalPay * 0.009,
  );

  const employeeClub = 10000;

  const totalDeduction =
    incomeTax +
    localIncomeTax +
    pension +
    health +
    employment +
    employeeClub;

  return {
    incomeTax,
    localIncomeTax,
    pension,
    health,
    employment,
    employeeClub,
    totalDeduction,
    netPay: Math.max(0, totalPay - totalDeduction),
  };
}

