function normalizeBonusAmount(entry) {
  const amount = Number(entry?.amount);
  return Number.isFinite(amount) && amount >= 0 ? amount : 0;
}

function getBonusEntriesForYear(year) {
  const yearKey = String(year);
  const savedEntries = Array.isArray(bonusEntriesByYear[yearKey])
    ? bonusEntriesByYear[yearKey]
    : [];
  const definitions = getBonusDefinitionsForYear(year);

  const entries = definitions.map((definition, index) => {
    const savedById = savedEntries.find(
      (entry) => entry?.id === definition.id,
    );
    const legacyEntry = savedById || savedEntries[index];

    return {
      ...definition,
      amount: normalizeBonusAmount(legacyEntry),
    };
  });

  bonusEntriesByYear[yearKey] = entries.map(
    ({ id, amount }) => ({ id, amount }),
  );

  return entries;
}

